-- Phase 20 hardening: emit domain events from existing services and recover abandoned deliveries.
create or replace function private.insert_integration_event(target_org uuid,target_store uuid,target_type text,target_aggregate text,target_id uuid,target_payload jsonb,target_origin text default'masterapp')returns text language plpgsql security definer set search_path='' as $$declare event_key text:='evt_'||replace(gen_random_uuid()::text,'-','');begin insert into public.integration_events(id,organization_id,store_id,event_type,aggregate_type,aggregate_id,origin,payload)values(event_key,target_org,target_store,target_type,target_aggregate,target_id,target_origin,target_payload);insert into public.webhook_deliveries(event_id,endpoint_id,organization_id)select event_key,e.id,e.organization_id from public.webhook_endpoints e where e.organization_id=target_org and e.status='active'and target_type=any(e.subscribed_events)and(e.store_id is null or e.store_id=target_store)and e.environment='production';return event_key;end$$;
revoke all on function private.insert_integration_event(uuid,uuid,text,text,uuid,jsonb,text)from public,anon,authenticated;

create or replace function private.emit_order_integration_event()returns trigger language plpgsql security definer set search_path='' as $$declare org uuid;kind text;begin select coalesce(organization_id,id)into org from public.establishments where id=new.establishment_id;if tg_op='INSERT'then kind:='order.created';elsif new.status is distinct from old.status then kind:=case when new.status='canceled'then'order.cancelled'else'order.updated'end;else return new;end if;perform private.insert_integration_event(org,new.establishment_id,kind,'order',new.id,jsonb_build_object('order_id',new.id,'order_number',new.order_number,'status',new.status,'total_cents',new.total_cents,'store_id',new.establishment_id,'updated_at',new.updated_at),case when new.source in('marketplace','custom_api')then new.source else'masterapp'end);return new;end$$;
create trigger orders_integration_event after insert or update of status on public.orders for each row execute function private.emit_order_integration_event();

create or replace function private.emit_customer_integration_event()returns trigger language plpgsql security definer set search_path='' as $$declare org uuid;begin select coalesce(organization_id,id)into org from public.establishments where id=new.establishment_id;perform private.insert_integration_event(org,new.establishment_id,'customer.created','customer',new.id,jsonb_build_object('customer_id',new.id,'name',new.name,'store_id',new.establishment_id),'masterapp');return new;end$$;
create trigger customers_integration_event after insert on public.customers for each row execute function private.emit_customer_integration_event();

create or replace function private.emit_reservation_integration_event()returns trigger language plpgsql security definer set search_path='' as $$begin perform private.insert_integration_event(new.organization_id,new.establishment_id,'reservation.created','reservation',new.id,jsonb_build_object('reservation_id',new.id,'code',new.reservation_code,'starts_at',new.starts_at,'party_size',new.party_size,'status',new.status,'store_id',new.establishment_id),'masterapp');return new;end$$;
create trigger reservations_integration_event after insert on public.reservations for each row execute function private.emit_reservation_integration_event();

create or replace function private.emit_inventory_integration_event()returns trigger language plpgsql security definer set search_path='' as $$declare org uuid;begin if new.needs_restock and(not old.needs_restock or old.needs_restock is null)then select coalesce(organization_id,id)into org from public.establishments where id=new.establishment_id;perform private.insert_integration_event(org,new.establishment_id,'inventory.low_stock','inventory_item',new.id,jsonb_build_object('inventory_item_id',new.id,'name',new.name,'balance',new.balance,'minimum',new.minimum,'store_id',new.establishment_id),'masterapp');end if;return new;end$$;
create trigger inventory_integration_event after update of balance,needs_restock on public.inventory_items for each row execute function private.emit_inventory_integration_event();

create or replace function private.emit_payment_integration_event()returns trigger language plpgsql security definer set search_path='' as $$declare org uuid;kind text;begin if new.status is not distinct from old.status then return new;end if;kind:=case when new.status='approved'then'payment.paid'when new.status in('declined','failed','cancelled','canceled')then'payment.failed'else null end;if kind is null then return new;end if;select coalesce(organization_id,id)into org from public.establishments where id=new.establishment_id;perform private.insert_integration_event(org,new.establishment_id,kind,'payment',new.id,jsonb_build_object('payment_id',new.id,'order_id',new.order_id,'status',new.status,'amount_cents',new.amount_cents,'provider',new.provider,'store_id',new.establishment_id),'masterapp');return new;end$$;
create trigger payments_integration_event after update of status on public.order_payment_transactions for each row execute function private.emit_payment_integration_event();

revoke all on function private.emit_order_integration_event(),private.emit_customer_integration_event(),private.emit_reservation_integration_event(),private.emit_inventory_integration_event(),private.emit_payment_integration_event()from public,anon,authenticated;

-- The order service already fires the order trigger, avoiding duplicated webhook events.
create or replace function public.integration_create_order(requested_store_id uuid,requested_payload jsonb,requested_origin text,requested_correlation_id text,requested_environment text default'production')returns jsonb language plpgsql security definer set search_path='' as $$declare store_slug text;result jsonb;order_id uuid;begin if current_setting('request.jwt.claim.role',true)<>'service_role' then raise exception'Operação interna.';end if;if requested_environment='sandbox'then return jsonb_build_object('order_id','00000000-0000-0000-0000-000000000000','order_number',0,'status','sandbox','sandbox',true);end if;select slug into store_slug from public.establishments where id=requested_store_id and active;if store_slug is null then raise exception'Unidade inválida.';end if;result:=public.place_public_order_v2(store_slug,requested_payload->>'customer_name',requested_payload->>'customer_phone',coalesce(requested_payload->>'fulfillment_type','pickup'),coalesce(requested_payload->'items','[]'::jsonb),requested_payload->>'notes',requested_payload->>'table_number','direct',requested_payload->>'payment_method',(requested_payload->>'cash_received_cents')::integer,requested_payload->'delivery_address');order_id:=(result->>'order_id')::uuid;update public.orders set source=case when requested_origin='marketplace'then'marketplace'else'custom_api'end,source_channel=case when requested_origin='marketplace'then'marketplace'else'api'end,order_source_channel=case when requested_origin='marketplace'then'marketplace'else'api'end where id=order_id;return result;end$$;
revoke all on function public.integration_create_order(uuid,jsonb,text,text,text)from public,anon,authenticated;grant execute on function public.integration_create_order(uuid,jsonb,text,text,text)to service_role;

create or replace function public.claim_webhook_deliveries(requested_limit integer default 20)returns table(delivery_id uuid,event_id text,endpoint_id uuid,url text,event_type text,payload jsonb,signing_secret text,attempt_count integer,request_id text)language plpgsql security definer set search_path='' as $$begin if current_setting('request.jwt.claim.role',true)<>'service_role'then raise exception'Operação interna.';end if;return query with claimed as(select d.id from public.webhook_deliveries d join public.webhook_endpoints e on e.id=d.endpoint_id where(d.status in('pending','retrying')and d.next_attempt_at<=now()or d.status='processing'and d.last_attempt_at<now()-interval'5 minutes')and e.status='active'order by d.next_attempt_at,d.created_at for update skip locked limit least(greatest(requested_limit,1),50)),updated as(update public.webhook_deliveries d set status='processing',attempt_count=d.attempt_count+1,last_attempt_at=now(),request_id=coalesce(d.request_id,'wh_'||replace(gen_random_uuid()::text,'-',''))from claimed c where d.id=c.id returning d.*)select u.id,u.event_id,u.endpoint_id,e.url,ev.event_type,ev.payload,v.decrypted_secret,u.attempt_count,u.request_id from updated u join public.webhook_endpoints e on e.id=u.endpoint_id join public.integration_events ev on ev.id=u.event_id join vault.decrypted_secrets v on v.id=e.vault_secret_id;end$$;
revoke all on function public.claim_webhook_deliveries(integer)from public,anon,authenticated;grant execute on function public.claim_webhook_deliveries(integer)to service_role;

do $$begin perform cron.unschedule('masterapp-phase20-cleanup')where exists(select 1 from cron.job where jobname='masterapp-phase20-cleanup');perform cron.schedule('masterapp-phase20-cleanup','17 3 * * *',$job$delete from public.api_rate_limit_buckets where bucket_start<now()-interval'2 days';delete from public.api_idempotency_keys where expires_at<now();$job$);end$$;
